  if (pManager->nNextSlotId == 0x7fffffff) {
    pManager->nNextSlotId = 0;
  }
  else {
    pManager->nNextSlotId = pManager->nNextSlotId + 1;
  }
  pFVar3 = *pArray;
  SmallArray_DestroySingleElement(&requestCopy.transformProvider);
  SmallArray_DestroySingleElement(&requestCopy.transformProvider);
  if (requestCopy.transformProvider.pHeapStorage != (void *)0x0) {
    FMemory_Free(requestCopy.transformProvider.pHeapStorage);
  }
  return pFVar3 + iVar2;
}

