/* Destroys a Lux particle-system component after clearing Lux-owned state.
   
   Algorithm:
   1. Release or clear the component's Lux material/root references.
   2. Set delayed-deactivation time at +0xAB8 to -1.0.
   3. Reset fade elapsed time at +0xAC4 to 0.0.
   4. Tail-call USceneComponent_DestroyComponent with the original promote-children flag.
   
   Parameters:
   pComponent - Lux particle-system component being destroyed.
   fPromoteChildren - Whether attached children should be promoted by inherited scene teardown.
   
   Returns:
   void.
   
   Source:
   Exact ULuxParticleSystemComponent destruction override on the dependent-particle cleanup route.
    */

void ULuxParticleSystemComponent_DestroyComponent
               (ULuxParticleSystemComponent_RollbackPartial *pComponent,bool fPromoteChildren)

{
  ClearLuxParticleDynamicMaterialRootFlags(pComponent);
  pComponent->flDelayedDeactivateTime = -1.0;
  pComponent->flFadeElapsed = 0.0;
  USceneComponent_DestroyComponent
            ((USceneComponent_WorldTransformOverlay *)pComponent,fPromoteChildren);
  return;
}
